import {validateMessage} from './validation.js';

// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.

describe('the websocket frame validator', () => {
  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  describe('list_sessions', () => {
    it('accepts a valid bare list_sessions frame, stripping unknown fields ([validated by: accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor](../../../specs/hal-engine-conversation-list/spec.md#L76))', () => {
      const result = validateMessage({type: 'list_sessions', userId: 'u1'});
      expect(result).toEqual({valid: true, data: {type: 'list_sessions'}});
    });

    it('accepts limit as a non-negative integer ([validated by: accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor](../../../specs/hal-engine-conversation-list/spec.md#L76))', () => {
      const result = validateMessage({type: 'list_sessions', limit: 10});
      expect(result).toEqual({valid: true, data: {type: 'list_sessions', limit: 10}});
    });

    it('rejects limit as a string ([validated by: accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor](../../../specs/hal-engine-conversation-list/spec.md#L76))', () => {
      expect(validateMessage({type: 'list_sessions', limit: '10'})).toEqual({
        valid: false,
        error: 'limit must be a non-negative integer',
      });
    });

    it('rejects limit as a negative integer ([validated by: accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor](../../../specs/hal-engine-conversation-list/spec.md#L76))', () => {
      expect(validateMessage({type: 'list_sessions', limit: -1})).toEqual({
        valid: false,
        error: 'limit must be a non-negative integer',
      });
    });

    it('rejects limit as a fractional number ([validated by: accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor](../../../specs/hal-engine-conversation-list/spec.md#L76))', () => {
      expect(validateMessage({type: 'list_sessions', limit: 1.5})).toEqual({
        valid: false,
        error: 'limit must be a non-negative integer',
      });
    });

    it('accepts a valid before cursor with string date ([validated by: accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor](../../../specs/hal-engine-conversation-list/spec.md#L76))', () => {
      const beforeStr = {sessionId: 's1', updatedAt: '2026-01-01T00:00:00Z'};
      expect(validateMessage({type: 'list_sessions', before: beforeStr})).toEqual({
        valid: true,
        data: {type: 'list_sessions', before: beforeStr},
      });
    });

    it('accepts a valid before cursor with number date ([validated by: accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor](../../../specs/hal-engine-conversation-list/spec.md#L76))', () => {
      const beforeNum = {sessionId: 's1', updatedAt: 1234567890};
      expect(validateMessage({type: 'list_sessions', before: beforeNum})).toEqual({
        valid: true,
        data: {type: 'list_sessions', before: beforeNum},
      });
    });

    it('rejects before as a non-object ([validated by: accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor](../../../specs/hal-engine-conversation-list/spec.md#L76))', () => {
      expect(validateMessage({type: 'list_sessions', before: 'not-an-object'})).toEqual({
        valid: false,
        error: 'before must be an object with sessionId and updatedAt',
      });
    });

    it('rejects before missing updatedAt ([validated by: accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor](../../../specs/hal-engine-conversation-list/spec.md#L76))', () => {
      expect(validateMessage({type: 'list_sessions', before: {sessionId: ''}})).toEqual({
        valid: false,
        error: 'before must be an object with sessionId and updatedAt',
      });
    });

    it('rejects before with invalid date string ([validated by: accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor](../../../specs/hal-engine-conversation-list/spec.md#L76))', () => {
      expect(validateMessage({type: 'list_sessions', before: {sessionId: 'a', updatedAt: 'not-a-date'}})).toEqual({
        valid: false,
        error: 'before.updatedAt must be a valid date string or number',
      });
    });

    it('rejects before with empty sessionId ([validated by: accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor](../../../specs/hal-engine-conversation-list/spec.md#L76))', () => {
